mapper.select:
SELECT ast.id, ast.exam_id AS examId, ast.user_id AS userId, u.name AS userName, u.employee_no AS employeeNo, d.name AS department, ast.status, ast.attempts_allowed AS attemptsAllowed, ast.attempts_used AS attemptsUsed, ast.deadline_at AS deadlineAt, ast.created_at AS createdAt FROM exam_assignment ast JOIN sys_user u ON u.id = ast.user_id LEFT JOIN department d ON d.id = u.department_id WHERE ast.exam_id = #{examId}
AND (u.name LIKE CONCAT('%', #{keyword}, '%') OR u.employee_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY ast.id
